"""Freeze the separately maintained interior extension before creating meshes."""
from pathlib import Path
import hashlib,json,os,subprocess
R=Path(__file__).resolve().parents[3];D=R/'art_source/scenes/gift_kiosk_interior/v001'
W=Path(os.environ.get('SEA_WORK_ROOT',R.parent/'sea-work'))/'gift_kiosk/interior/v001'
D.mkdir(parents=True,exist_ok=True);W.mkdir(parents=True,exist_ok=True)
assert not (D/'component_plan.json').exists(),'Frozen plan already exists'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
rows=[('tile_cream','奶油地砖','floor_tile','structure'),('tile_blue','海蓝地砖','floor_tile','structure'),('tile_honey','蜜黄地砖','floor_tile','structure'),('checkout_counter','圆角收银柜台','counter','furnishing'),('cash_register','复古收银机','register','furnishing'),('display_table','椭圆礼品陈列台','display','furnishing'),('stool','圆坐凳','seat','furnishing'),('wall_poster','海岸主题装饰画','wall_art','furnishing'),('wall_clock','圆挂钟','clock','furnishing'),('wall_sconce','壁灯','lamp','furnishing'),('cubby','礼品包装柜','cabinet','furnishing')]
plan={'schema':'sea.scene.component_plan','feature_id':'SEA-ASSET','clause':'SEA-ASSET-R57','world_clause':'SEA-WORLD-R27','version':'v001','status':'frozen_before_geometry','asset_id':'SEA-SCENE-GKI-ASSEMBLY','building_class':'above_water','loaded_responsibility':'references/above-water.md','scope':'scene_local interior furnishing extension; original 47-component exterior suite is protected and not regenerated','palette':'art_source/shared/palettes/sea_cozy_8x8_512.png','palette_exception':'Continue the existing kiosk bright cozy palette, no palette change or duplicate','reference':'art_source/scenes/gift_kiosk/v001/reference.png','reference_sha256':sha(R/'art_source/scenes/gift_kiosk/v001/reference.png'),'reference_license':'pending_user_reference_commercial_rights_review','dimensions':{'tile_pitch':0.94,'tile_width':0.93,'tile_height':0.02,'floor_top_local':0.315,'counter_height':1.25,'display_height':1.02,'stool_height':0.65},'style':'Plump real 3-segment bevels; cream, sea blue and honey flooring; teal cabinet fronts and honey wood tops; no realistic wear','exceptions':['Interior is a separately maintained 11-component extension, not a rewrite of the 47-component exterior suite.','Three floor swatch variants have identical topology and dimensions; only PaletteUV changes. They share one floor semantic family and the same public material.','Thin inlaid tiles use 0.006m bevel constrained by their thickness; fixed furniture uses 0.04-0.12m real bevels.'],'locked':['all original exterior component sources and GLBs','all original 379 instance transforms','main.tscn user placement','roof reveal metadata and controller','original water blockers, landing and float behavior'],'runtime':{'stable_parent':'godot/scenes/facilities/floating_shop.tscn','stable_scene':'godot/scenes/facilities/gift_kiosk_interior.tscn','zone_id':'sea_supply','interaction':'move existing SupplyCounter to the new real counter customer side; preserve existing supply service'},'components':[{'key':k,'asset_id':'SEA-SCENE-GKI-'+k.upper().replace('_','-'),'name':n,'family':f,'group':g,'building_class':'above_water' if g=='structure' else None,'origin':'bottom_center','front_axis':'-Y -> Godot +Z','budget':None,'budget_source':'No user face cap; reference silhouette and actual camera fidelity'} for k,n,f,g in rows]}
(D/'component_plan.json').write_text(json.dumps(plan,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
paths=[R/'godot/scenes/main.tscn',R/'godot/scenes/facilities/floating_shop.tscn',R/plan['palette']]
paths+=list((R/'art_source/scenes/gift_kiosk/v001').rglob('*.blend'))
paths+=list((R/'godot/assets/models/facilities/gift_kiosk').rglob('*.glb'))
(W/'scope_before.json').write_text(json.dumps({'protected_files':{p.relative_to(R).as_posix():sha(p) for p in paths},'git_status':subprocess.check_output(['git','status','--porcelain'],cwd=R,text=True)},ensure_ascii=False,indent=2),encoding='utf-8')
print('Frozen',len(rows),'interior components and',len(paths),'protected files')
